package org.sleepwell.app;

import android.content.Context;
import android.database.sqlite.SQLiteDatabase;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.Test;
import java.io.*;
import java.util.*;
import java.util.zip.*;
import static org.junit.Assert.*;

/** Owned SQLite/WAV/ZIP bytes only. No playback, capture, settings or cue allocation. */
public class SoundLabelStorageTest {
    private Context context(){return InstrumentationRegistry.getInstrumentation().getTargetContext();}
    private void preserved(JSONObject before,JSONObject after){for(String key:new String[]{"id","session","time","duration_ms","category","score","model","clip","favorite"})assertEquals(key,before.opt(key),after.opt(key));}
    @Test public void linkedClipSnapshotRoundTripAcceptsSameIdAndRejectsRemovedChangedAndNewLinks()throws Exception{try(SoundLabelFixture f=new SoundLabelFixture(context());Store store=f.open()){
        SoundLabels.Snapshot linked=f.snapshot(store);long event=linked.event.getLong("id"),clip=linked.event.getLong("clip");byte[] wav=java.nio.file.Files.readAllBytes(f.file.toPath());assertEquals(clip,SoundLabels.check(store,linked).getLong("clip"));
        store.getWritableDatabase().execSQL("UPDATE sound_events SET clip=NULL WHERE id=?",new Object[]{event});try{SoundLabels.save(store,linked,"speech");fail("Removing a clip must invalidate the original draft");}catch(IllegalArgumentException expected){}assertTrue(f.event(store).isNull("user_category"));assertEquals(0,f.event(store).getLong("label_revision"));SoundLabels.Snapshot unlinked=f.snapshot(store);assertTrue(SoundLabels.check(store,unlinked).isNull("clip"));
        store.getWritableDatabase().execSQL("UPDATE sound_events SET clip=? WHERE id=?",new Object[]{clip,event});try{SoundLabels.save(store,unlinked,"speech");fail("A new link must invalidate an unlinked draft");}catch(IllegalArgumentException expected){}assertEquals(clip,SoundLabels.check(store,linked).getLong("clip"));
        store.getWritableDatabase().execSQL("UPDATE sound_events SET clip=? WHERE id=?",new Object[]{clip+1,event});try{SoundLabels.save(store,linked,"speech");fail("Changing the linked clip must invalidate the draft");}catch(IllegalArgumentException expected){}assertTrue(f.event(store).isNull("user_category"));assertEquals(0,f.event(store).getLong("label_revision"));assertArrayEquals(wav,java.nio.file.Files.readAllBytes(f.file.toPath()));
    }}
    @Test public void correctionResetAndEffectiveCountsPreserveOriginalsAndWaveBytes()throws Exception{try(SoundLabelFixture f=new SoundLabelFixture(context());Store store=f.open()){
        JSONObject before=f.event(store);byte[] wav=java.nio.file.Files.readAllBytes(f.file.toPath());SoundLabels.save(store,f.snapshot(store),"speech");JSONObject after=f.event(store);preserved(before,after);assertEquals("snoring",after.getString("category"));assertEquals("speech",SoundLabels.category(after));assertTrue(SoundLabels.manual(after));assertEquals(1,after.getLong("label_revision"));RecordEntry night=Records.get(store,1);ReportSounds report=ReportSounds.read(context(),store,night);assertEquals(0,report.snoring);assertEquals(2,report.speech);assertEquals(1,report.userLabels);assertEquals(1,report.analysisOnly);List<SoundEventRows.Row> rows=SoundEventRows.metadata(context(),store,night);assertEquals("Speech · Your label",rows.get(0).title);assertTrue(SoundEventRows.matches(rows.get(0),"speech"));assertFalse(SoundEventRows.matches(rows.get(0),"snoring"));assertEquals(1,FavoriteSoundRows.read(context(),store,new FavoriteSoundRows.Filter(0,"speech"),0,System.currentTimeMillis()).total);assertEquals(0,FavoriteSoundRows.read(context(),store,new FavoriteSoundRows.Filter(0,"snoring"),0,System.currentTimeMillis()).total);
        SoundLabels.save(store,f.snapshot(store),"cough");assertEquals(2,f.event(store).getLong("label_revision"));assertEquals(1,ReportSounds.read(context(),store,night).other);assertEquals(1,FavoriteSoundRows.read(context(),store,new FavoriteSoundRows.Filter(0,"noise"),0,System.currentTimeMillis()).total);assertTrue(SoundEventRows.matches(SoundEventRows.metadata(context(),store,night).get(0),"noise"));SoundLabels.save(store,f.snapshot(store),null);JSONObject reset=f.event(store);preserved(before,reset);assertTrue(reset.isNull("user_category"));assertEquals(3,reset.getLong("label_revision"));assertEquals("Snoring estimate",SoundEventRows.metadata(context(),store,night).get(0).title);assertArrayEquals(wav,java.nio.file.Files.readAllBytes(f.file.toPath()));try(Store reopened=f.open()){preserved(before,f.event(reopened));assertTrue(f.event(reopened).isNull("user_category"));}
    }}
    @Test public void staleRevisionTrimDeletedEventAndInvalidChoiceRejectTransactionally()throws Exception{try(SoundLabelFixture f=new SoundLabelFixture(context());Store store=f.open()){
        SoundLabels.Snapshot stale=f.snapshot(store);SoundLabels.save(store,stale,"speech");String saved=f.event(store).toString();try{SoundLabels.save(store,stale,"noise");fail("Stale label revision");}catch(IllegalArgumentException expected){}assertEquals(saved,f.event(store).toString());try{SoundLabels.save(store,f.snapshot(store),"diagnosis");fail("Unknown label");}catch(IllegalArgumentException expected){}assertEquals(saved,f.event(store).toString());SoundLabels.Snapshot trim=f.snapshot(store);RecordEntry night=Records.get(store,1);RecordDraft draft=new RecordDraft(f.start+5000,f.start+10000);Records.save(store,1,draft,night.updated,System.currentTimeMillis());try{SoundLabels.save(store,trim,"noise");fail("Fresh edited bounds must win");}catch(IllegalArgumentException expected){}assertEquals(saved,f.event(store).toString());store.getWritableDatabase().delete("sound_events","id=?",new String[]{""+trim.event.getLong("id")});try{SoundLabels.save(store,trim,"noise");fail("Deleted event");}catch(IllegalArgumentException expected){}assertTrue(f.file.exists());
    }}
    @Test public void abaChangesAndCounterOverflowCannotAuthorizeStaleDrafts()throws Exception{try(SoundLabelFixture f=new SoundLabelFixture(context());Store store=f.open()){
        SoundLabels.Snapshot original=f.snapshot(store);SoundLabels.save(store,original,"speech");SoundLabels.save(store,f.snapshot(store),null);assertEquals(2,f.event(store).getLong("label_revision"));assertTrue(f.event(store).isNull("user_category"));try{SoundLabels.save(store,original,"noise");fail("ABA reset must not revive the original draft even with no clock advance");}catch(IllegalArgumentException expected){}assertEquals(2,f.event(store).getLong("label_revision"));
        store.getWritableDatabase().execSQL("UPDATE sound_events SET label_revision=9007199254740991 WHERE id=?",new Object[]{original.event.getLong("id")});try{SoundLabels.save(store,f.snapshot(store),"speech");fail("Exact portable counter overflow must reject before SQLite REAL promotion");}catch(IllegalArgumentException expected){}assertEquals("integer",store.rows("SELECT typeof(label_revision) AS kind FROM sound_events ORDER BY time LIMIT 1").get(0).getString("kind"));assertTrue(f.event(store).isNull("user_category"));
    }}
    @Test public void portableMetadataRoundTripsCorrectionsAndLegacyFormatsRemainReadable()throws Exception{Context c=context();String restored="sleepwell-verification-"+UUID.randomUUID()+".db";try(SoundLabelFixture f=new SoundLabelFixture(c);Store source=f.open();Store target=new Store(c,restored)){
        SoundLabels.save(source,f.snapshot(source),"speech");JSONObject backup=source.backup();assertEquals(4,backup.getInt("format"));Backup.validate(backup);assertEquals(2,backup.getJSONArray("sound_events").length());assertFalse(backup.toString().contains(f.file.getName()));assertFalse(backup.getJSONArray("sound_events").getJSONObject(0).has("clip"));Backup.restoreData(target,backup);JSONObject row=f.event(target);assertEquals("snoring",row.getString("category"));assertEquals("speech",row.getString("user_category"));assertEquals(1,row.getLong("label_revision"));assertTrue(row.isNull("clip"));assertEquals(1,row.getInt("favorite"));assertTrue(target.rows("SELECT id FROM clips").isEmpty());assertTrue(f.file.exists());
        String preserved=target.backup().toString();for(String key:List.of("category","user_category","model","time","duration_ms","score","session","favorite","label_revision","clip")){JSONObject bad=new JSONObject(backup.toString());JSONObject event=bad.getJSONArray("sound_events").getJSONObject(0);switch(key){case "category":case "user_category":event.put(key,"invalid");break;case "model":event.put(key,"");break;case "time":event.put(key,"1234");break;case "duration_ms":event.put(key,0);break;case "score":event.put(key,1.1);break;case "session":event.put(key,999);break;case "favorite":event.put(key,2);break;case "label_revision":event.put(key,-1);break;default:event.put(key,"/not/a/path");}try{Backup.restoreData(target,bad);fail("Reject invalid portable "+key);}catch(JSONException expected){}assertEquals(preserved,target.backup().toString());}
        for(int version:new int[]{1,2,3}){JSONObject old=new JSONObject(backup.toString()).put("format",version);old.remove("sound_events");Backup.restoreData(target,old);assertTrue(target.rows("SELECT id FROM sound_events").isEmpty());assertEquals(1,target.rows("SELECT id FROM sessions").size());}
    }finally{c.deleteDatabase(restored);}}
    @Test public void portableMetadataCountTypesAndEndedSessionReferencesAreStrictlyBounded()throws Exception{try(SoundLabelFixture f=new SoundLabelFixture(context());Store store=f.open()){
        JSONObject root=store.backup();for(String variant:List.of("duplicate","unfinished","fraction","modelLength","tooMany")){JSONObject bad=new JSONObject(root.toString());JSONArray rows=bad.getJSONArray("sound_events");JSONObject first=rows.getJSONObject(0);switch(variant){case "duplicate":rows.getJSONObject(1).put("id",first.getLong("id"));break;case "unfinished":bad.getJSONArray("sessions").getJSONObject(0).put("end",JSONObject.NULL);break;case "fraction":first.put("label_revision",1.5);break;case "modelLength":first.put("model","x".repeat(129));break;default:JSONArray huge=new JSONArray();for(int n=0;n<=SoundEventBackup.MAX_EVENTS;n++)huge.put(first);bad.put("sound_events",huge);}try{Backup.validate(bad);fail("Reject portable limit/reference/type "+variant);}catch(JSONException expected){}}
        JSONObject unicode=new JSONObject(root.getJSONArray("sound_events").getJSONObject(0).toString()).put("model","界".repeat(128));JSONArray wide=new JSONArray();for(int n=0;n<20000;n++)wide.put(unicode);assertTrue("Wide metadata character count alone fits",wide.toString().length()<SoundEventBackup.MAX_JSON);assertTrue("UTF8 metadata bytes, not just character count, are bounded",SoundEventBackup.oversized(wide));
        try{SoundEventBackup.checkPortableSize(new JSONObject().put("large", "x".repeat(8*1024*1024)));fail("Pretty UTF8 total must fit existing eight MiB file importer");}catch(IllegalArgumentException expected){}
        assertEquals(2,store.rows("SELECT id FROM sound_events").size());assertTrue(f.file.exists());
    }}
    @Test public void archiveKeepsOriginalAndUserProvenanceAndRejectsChangedLabelsBeforeOutput()throws Exception{try(SoundLabelFixture f=new SoundLabelFixture(context());Store store=f.open()){
        NightAudioArchive.Plan stale=NightAudioArchive.prepare(context(),store,1,Records.get(store,1).updated);SoundLabels.save(store,f.snapshot(store),"speech");ByteArrayOutputStream untouched=new ByteArrayOutputStream();try{NightAudioArchive.write(context(),store,stale,untouched);fail("Correction invalidates old plan");}catch(IOException expected){}assertEquals(0,untouched.size());ByteArrayOutputStream bytes=new ByteArrayOutputStream();NightAudioArchive.write(context(),store,NightAudioArchive.prepare(context(),store,1,Records.get(store,1).updated),bytes);JSONObject manifest=null;try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(bytes.toByteArray()))){for(ZipEntry entry;(entry=zip.getNextEntry())!=null;){ByteArrayOutputStream output=new ByteArrayOutputStream();byte[] buffer=new byte[8192];for(int n;(n=zip.read(buffer))!=-1;)output.write(buffer,0,n);if(entry.getName().equals("manifest.json"))manifest=new JSONObject(output.toString("UTF-8"));else assertArrayEquals(java.nio.file.Files.readAllBytes(f.file.toPath()),output.toByteArray());}}assertNotNull(manifest);JSONObject event=manifest.getJSONArray("sound_events").getJSONObject(0);assertEquals("snoring",event.getString("category"));assertEquals("speech",event.getString("effective_category"));assertEquals("user",event.getString("label_source"));assertEquals(.9,event.getDouble("score"),0);assertTrue(f.file.exists());
    }}
    @Test public void crashRecoveryUsesDurableSoundEndsWithAndWithoutAnEpochAndBacksUpExactly()throws Exception{Context c=context();String source="sleepwell-verification-"+UUID.randomUUID()+".db",destination="sleepwell-verification-"+UUID.randomUUID()+".db";try(Store store=new Store(c,source);Store restored=new Store(c,destination)){
        long start=System.currentTimeMillis()-3600000;for(int id:new int[]{1,2}){long from=start+id*60000;store.getWritableDatabase().execSQL("INSERT INTO sessions(id,start,end,active_ms,source,origin,zone) VALUES(?,?,NULL,0,'tracked','local','UTC')",new Object[]{id,from});if(id==2)store.epoch(id,from,from+1000,.2,null,null,10);store.soundEvent(id,from+5000,1950,"snoring",.9,null);}
        List<JSONObject> original=store.rows("SELECT * FROM sound_events ORDER BY id");store.recoverInterrupted();for(int id:new int[]{1,2}){JSONObject night=store.rows("SELECT * FROM sessions WHERE id=?",""+id).get(0);assertEquals(start+id*60000+6950,night.getLong("end"));assertEquals(0,night.getLong("active_ms"));assertEquals(1,night.getInt("interrupted"));JSONObject event=SoundClips.event(store,id,original.get(id-1).getLong("id"));preserved(original.get(id-1),event);RecordEntry record=Records.get(store,id);SoundLabels.save(store,new SoundLabels.Snapshot(event,record.updated,record.edit.start,record.edit.end),"speech");}
        assertEquals(1,store.rows("SELECT id FROM epochs").size());JSONObject backup=store.backup();Backup.validate(backup);for(int n=0;n<2;n++)assertEquals("raw_session",backup.getJSONArray("sound_events").getJSONObject(n).getString("interval_scope"));Backup.restoreData(restored,backup);assertEquals(1,restored.rows("SELECT id FROM epochs").size());for(JSONObject event:restored.rows("SELECT * FROM sound_events")){assertEquals("snoring",event.getString("category"));assertEquals("speech",event.getString("user_category"));assertEquals(1,event.getLong("label_revision"));assertEquals(.9,event.getDouble("score"),0);assertEquals(YamnetClassifier.MODEL_ID,event.getString("model"));assertTrue(event.isNull("clip"));}assertTrue(restored.rows("SELECT id FROM clips").isEmpty());
    }finally{c.deleteDatabase(source);c.deleteDatabase(destination);}}
    @Test public void alreadyRecoveredInterruptedTailPreservesRawNightAndEstimateWithoutClamping()throws Exception{Context c=context();String source="sleepwell-verification-"+UUID.randomUUID()+".db",destination="sleepwell-verification-"+UUID.randomUUID()+".db";try(Store store=new Store(c,source);Store restored=new Store(c,destination)){
        long start=System.currentTimeMillis()-3600000;store.getWritableDatabase().execSQL("INSERT INTO sessions(id,start,end,interrupted,source,origin,zone) VALUES(1,?,?,1,'tracked','local','UTC')",new Object[]{start,start+1000});store.soundEvent(1,start+5000,1950,"snoring",.9,null);store.getWritableDatabase().execSQL("UPDATE sound_events SET user_category='speech',label_revision=7");JSONObject before=store.rows("SELECT * FROM sound_events").get(0);JSONObject backup=store.backup();assertEquals("interrupted_tail",backup.getJSONArray("sound_events").getJSONObject(0).getString("interval_scope"));Backup.validate(backup);Backup.restoreData(restored,backup);assertEquals(start+1000,restored.rows("SELECT end FROM sessions").get(0).getLong("end"));JSONObject after=restored.rows("SELECT * FROM sound_events").get(0);preserved(before,after);assertEquals("speech",after.getString("user_category"));assertEquals(7,after.getLong("label_revision"));assertEquals(before.getLong("time"),after.getLong("time"));assertEquals(before.getLong("duration_ms"),after.getLong("duration_ms"));assertTrue(after.isNull("clip"));
        for(String variant:List.of("normalOverflow","forgedScope","beyondBound","forgedTailInside")){JSONObject bad=new JSONObject(backup.toString());JSONObject event=bad.getJSONArray("sound_events").getJSONObject(0);switch(variant){case "normalOverflow":bad.getJSONArray("sessions").getJSONObject(0).put("interrupted",0);break;case "forgedScope":event.put("interval_scope","raw_session");break;case "beyondBound":event.put("time",start+36*3600000L);break;default:event.put("time",start).put("duration_ms",500);}try{Backup.validate(bad);fail("Reject forged/mismatched interrupted scope "+variant);}catch(JSONException expected){}}
        assertEquals(start+1000,store.rows("SELECT end FROM sessions").get(0).getLong("end"));assertEquals(before.toString(),store.rows("SELECT * FROM sound_events").get(0).toString());
    }finally{c.deleteDatabase(source);c.deleteDatabase(destination);}}
    @Test public void versionSixMigrationPreservesAllExistingColumnsAndRows()throws Exception{Context c=context();String name="sleepwell-verification-"+UUID.randomUUID()+".db";try(SoundLabelFixture f=new SoundLabelFixture(c);Store seed=f.open()){
        Alarm preservedAlarm=new Alarm(91);preservedAlarm.enabled=false;seed.save(preservedAlarm);RecordEntry raw=Records.get(seed,1);RecordDraft edited=new RecordDraft(raw.edit.start,raw.edit.end);edited.note="Preserve edited note";edited.addTag("fixture");Records.save(seed,1,edited,raw.updated,System.currentTimeMillis());seed.pause(1,f.start+3000);seed.resume(1,f.start+3500);seed.getWritableDatabase().execSQL("INSERT INTO pending_clip_deletes VALUES(99,1,'verification-missing-journal.wav',?)",new Object[]{f.start});
        List<JSONObject> schema=seed.rows("SELECT type,name,sql FROM sqlite_master WHERE sql IS NOT NULL AND name NOT LIKE 'sqlite_%' AND name!='android_metadata' ORDER BY CASE type WHEN 'table' THEN 0 WHEN 'index' THEN 1 ELSE 2 END,name");Map<String,String> selections=new LinkedHashMap<>(),expected=new LinkedHashMap<>();
        for(JSONObject object:schema)if(object.getString("type").equals("table")){String table=object.getString("name");List<String> columns=new ArrayList<>();for(JSONObject col:seed.rows("PRAGMA table_info("+table+")")){String column=col.getString("name");if(!Set.of("user_category","label_revision").contains(column))columns.add(column);}String select="SELECT "+String.join(",",columns)+" FROM "+table+" ORDER BY 1";selections.put(table,select);expected.put(table,seed.rows(select).toString());}
        try(SQLiteDatabase old=SQLiteDatabase.openOrCreateDatabase(c.getDatabasePath(name),null)){for(JSONObject object:schema){String sql=object.getString("sql");if(object.getString("name").equals("sound_events")&&object.getString("type").equals("table"))sql=sql.replaceAll(",\\s*user_category TEXT","").replaceAll(",\\s*label_revision INTEGER NOT NULL DEFAULT 0","");old.execSQL(sql);}old.execSQL("ATTACH DATABASE ? AS seed",new Object[]{c.getDatabasePath(f.database).getAbsolutePath()});for(Map.Entry<String,String> entry:selections.entrySet()){String table=entry.getKey();String query=entry.getValue().replace(" FROM "+table," FROM seed."+table);old.execSQL("INSERT INTO "+table+" "+query);}old.execSQL("DETACH DATABASE seed");old.setVersion(6);}
        try(Store upgraded=new Store(c,name)){assertEquals(7,upgraded.getReadableDatabase().getVersion());for(Map.Entry<String,String> entry:selections.entrySet())assertEquals(entry.getKey(),expected.get(entry.getKey()),upgraded.rows(entry.getValue()).toString());assertTrue(f.event(upgraded).isNull("user_category"));assertEquals(0,f.event(upgraded).getLong("label_revision"));assertEquals("ok",upgraded.rows("PRAGMA integrity_check").get(0).getString("integrity_check"));}assertTrue(f.file.exists());
    }finally{c.deleteDatabase(name);}}
}
